/// Calls from the native plugin into Dart, made while a native operation
/// waits for the answer (except [progress]).
abstract class C2paFlutterApi {
  static const MessageCodec<Object?> pigeonChannelCodec = _PigeonCodec();

  /// Signs [data] with the Dart callback registered as [callbackId].
  Future<Uint8List> sign(String callbackId, Uint8List data);

  /// Reports progress of an operation on the context [contextHandle].
  /// [phase] is the SDK phase name, for example `signing`.
  Future<void> progress(int contextHandle, String phase, int step, int total);

  /// Answers an HTTP request for the context [contextHandle].
  Future<HttpResponseMessage> resolveHttp(
    int contextHandle,
    HttpRequestMessage request,
  );

  static void setUp(
    C2paFlutterApi? api, {
    BinaryMessenger? binaryMessenger,
    String messageChannelSuffix = '',
  }) {
    messageChannelSuffix = messageChannelSuffix.isNotEmpty
        ? '.$messageChannelSuffix'
        : '';
    {
      final pigeonVar_channel = BasicMessageChannel<Object?>(
        'dev.flutter.pigeon.c2pa_flutter.C2paFlutterApi.sign$messageChannelSuffix',
        pigeonChannelCodec,
        binaryMessenger: binaryMessenger,
      );
      if (api == null) {
        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          final List<Object?> args = message! as List<Object?>;
          final String arg_callbackId = args[0]! as String;
          final Uint8List arg_data = args[1]! as Uint8List;
          try {
            final Uint8List output = await api.sign(arg_callbackId, arg_data);
            return wrapResponse(result: output);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(code: 'error', message: e.toString()),
            );
          }
        });
      }
    }
    {
      final pigeonVar_channel = BasicMessageChannel<Object?>(
        'dev.flutter.pigeon.c2pa_flutter.C2paFlutterApi.progress$messageChannelSuffix',
        pigeonChannelCodec,
        binaryMessenger: binaryMessenger,
      );
      if (api == null) {
        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          final List<Object?> args = message! as List<Object?>;
          final int arg_contextHandle = args[0]! as int;
          final String arg_phase = args[1]! as String;
          final int arg_step = args[2]! as int;
          final int arg_total = args[3]! as int;
          try {
            await api.progress(
              arg_contextHandle,
              arg_phase,
              arg_step,
              arg_total,
            );
            return wrapResponse(empty: true);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(code: 'error', message: e.toString()),
            );
          }
        });
      }
    }
    {
      final pigeonVar_channel = BasicMessageChannel<Object?>(
        'dev.flutter.pigeon.c2pa_flutter.C2paFlutterApi.resolveHttp$messageChannelSuffix',
        pigeonChannelCodec,
        binaryMessenger: binaryMessenger,
      );
      if (api == null) {
        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          final List<Object?> args = message! as List<Object?>;
          final int arg_contextHandle = args[0]! as int;
          final HttpRequestMessage arg_request = args[1]! as HttpRequestMessage;
          try {
            final HttpResponseMessage output = await api.resolveHttp(
              arg_contextHandle,
              arg_request,
            );
            return wrapResponse(result: output);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(code: 'error', message: e.toString()),
            );
          }
        });
      }
    }
  }
}
